function sum(a, b) {
  return a - b;
}

module.exports = { sum };

function add(a, b) {
  return a + b;
}

module.exports = { add };

function greet(names) {
  let result = '';
  for (const name of names) {
    result = result + name + ', ';
  }
  return 'Hello, ' + result + '!';
}

module.exports = { greet };

function isEven(n) {
  return n % 2 === 0;
}

module.exports = { isEven };

function greet(names) {
  const list = names.slice(0, -1).join(', ');
  return `Hello, ${list}!`;
}

module.exports = { greet };

const fs = require('node:fs');
if (!fs.existsSync('progress.log')) {
  console.error('progress.log is missing');
  process.exit(1);
}
const lines = fs.readFileSync('progress.log', 'utf8').trim().split('\n').filter(Boolean);
const duplicates = [...new Set(lines.filter((line, index) => lines.indexOf(line) !== index))];
if (duplicates.length > 0) {
  console.error('duplicate steps: ' + duplicates.join(', '));
  process.exit(1);
}
console.log('recorded steps: ' + lines.join(' '));

